save('6B5C41','а) сумма косинусов 3/2; б) √6/36',[
 ('Связать радиус и высоту с образующей конуса','Пусть образующая l. Угол с основанием 60° даёт R=l/2,h=√3 l/2; AB=2R=l. Все образующие SA,SB,SC равны l.',['cone','trigratio'],['condition']),
 ('а) Выразить косинусы через хорды и сложить','По теореме косинусов cos ASC=1-AC²/(2l²), cos BSC=1-BC²/(2l²). Угол ACB прямой как вписанный на диаметре AB, поэтому AC²+BC²=AB²=l². Сумма равна 2-1/2=3/2.',['cos','diameter','pyth'],['condition','s1']),
 ('б) Найти стороны и площадь треугольника основания тетраэдра','При l=1 и cos ASC=2/3 имеем AC²=2/3. Тогда BC²=1/3, S(ABC)=AC·BC/2=√2/6.',['cos','triarea'],['condition','s1','s2']),
 ('б) Вычислить объём по площади и высоте','Высота S над плоскостью ABC равна h=√3/2. V(SABC)=S(ABC)h/3=(√2/6)(√3/2)/3=√6/36.',['pyrvolume'],['s1','s3'])],
 [('cone','Связывать параметры прямого конуса через осевое сечение','Использовать прямоугольный треугольник радиуса, высоты и образующей и проекцию образующей на основание.'),
 ('trigratio','Находить стороны прямоугольного треугольника по углу','Использовать синус и косинус угла с известной гипотенузой.'),
 ('cos','Применять теорему косинусов','Связать стороны и косинус угла между ними в невырожденном треугольнике.'),
 ('diameter','Использовать прямой вписанный угол на диаметре','Для точки окружности получить прямой угол, опирающийся на диаметр.'),
 ('pyth','Применять теорему Пифагора к прямоугольному треугольнику','Связать квадраты катетов и гипотенузы после установления прямого угла.'),
 ('triarea','Находить площадь прямоугольного треугольника','Вычислить половину произведения двух перпендикулярных катетов.'),
 ('pyrvolume','Вычислять объём пирамиды','Умножить площадь основания на перпендикулярную высоту и разделить на три.')],
 [('а) Сложить косинусы по теореме косинусов и диаметру',[1,2]),('б) Найти площадь основания и высоту тетраэдра',[1,2,3,4])])

