save('E1812B','10 тыс. рублей за единицу',[
 ('Построить функцию прибыли и условие окупаемости','Π(x)=-x²/2+(p-2)x-6, x≥0. Для окупаемости не более чем за 3 года требуется max Π≥78/3=26 млн в год.',['model'],['condition']),
 ('Найти максимальную прибыль выделением квадрата','Π(x)=-(x-(p-2))²/2+(p-2)²/2-6. При p>2 максимум при x=p-2 и равен (p-2)²/2-6. При p≤2 максимум на x≥0 равен -6 в x=0 и окупаемость невозможна.',['quadmax','boundary'],['s1']),
 ('Решить ограничение на цену','При p>2: (p-2)²/2-6≥26 ⇒ (p-2)²≥64 ⇒ p≥10. Другую ветвь p≤-6 исключает p>2.',['squareineq','sets'],['s1','s2']),
 ('Проверить минимальную цену и объём выпуска','При p=10 оптимальный выпуск x=8 тыс., прибыль 80-(32+16+6)=26 млн в год; за три года 78 млн. Минимальная цена 10 тыс. рублей.',['attain'],['s1','s2','s3'])],
 [('model','Моделировать прибыль и срок окупаемости','Связать выручку, затраты, допустимый выпуск и инвестиции с суммарной прибылью за заданный срок, согласовав единицы.'),
 ('quadmax','Находить максимум квадратной функции выделением квадрата','Для вогнутой квадратичной функции получить вершину и максимальное значение через полный квадрат.'),
 ('boundary','Учитывать ограничение области при оптимизации','Проверить, принадлежит ли вершина допустимой области, иначе исследовать её границу.'),
 ('squareineq','Решать квадратное неравенство с параметром','Из ограничения на квадрат получить обе ветви и учесть дополнительные знаковые ограничения.'),
 ('sets','Пересекать множества допустимых значений','Совместить ограничения и исключить неподходящие ветви решения.'),
 ('attain','Доказывать оптимальность оценкой и достижимостью','Предъявить допустимые параметры, достигающие доказанной границы, и проверить исходные условия.')],
 [('Оптимизировать выпуск при данной цене, затем найти порог окупаемости',[1,2,3,4])])

